function grid$m48_1Distribute(f){
  this.constructor(f);
}
grid$m48_1Distribute.prototype = new DirEvent();
grid$m48_1Distribute.prototype.cellFocus = function(o){
  DirEvent.prototype.cellFocus.apply(this, arguments);
  this.reloadInvGrid(o);
}
grid$m48_1Distribute.prototype.beforeInit = function(renderType){
  var p = this._dir;
  if (renderType == 0) {
    $("<div>").addClass('bottom-resize').attr('id', 'bar_resize_grid').appendTo($("#content"))
    p.options.renderCompleted = function() {
      var g = p.grid(), dt = g.data, m = new Memvars(), r = (dt.count() > 0)? 0: null;
      if (r == null){
        m.add([['id', 'I', 0], ['xu_ly', 'I', p.options._xu_ly], ['ma_kh', 'C', ''], ['ma_nt', 'C', ''], ['unit_id', 'I', 0], ['tien_nt', 'N', 0]]);
        p.options._currentCode = '#'
      }
      else {
        m.add([['id', 'I', dt.val(r, 'id')], ['xu_ly', 'I', p.options._xu_ly], ['ma_kh', 'C', dt.val(r, 'ma_kh')], ['unit_id', 'I', dt.val(r, 'unit_id')], ['ma_nt', 'C', dt.val(r, 'ma_nt')], ['tien_nt', 'N', dt.val(r, 'tien_nt')]]);
        p.options._currentCode = dt.val(r, 'ma_kh') + '#' + dt.val(r, 'id');
      }

      p.options._dirHD = $.createDir(false, { controller: "m48_1Distribute2", memvars: m, focusWhenCreated: false, applyShortWhenCreated: false, folder: "Grid", dirViewType: "",subtitle:"", dirAbove: p, renderCompleted: function() {
        var gridDir = $("#content").find(".dir");
        var oG1Resize = $(gridDir.get(0));
        var oG2Resize = $(gridDir.get(1));
        $("#bar_resize_grid").boxresize({ divBox1: oG1Resize, divBox2: oG2Resize, resizeWidth: false});
      } });
      p.options.renderCompleted = null;
    }
  }
}
grid$m48_1Distribute.prototype.afterInit = function(renderType){
  var p = this._dir;
  if (renderType == 0) {
    var wHeight = $(window).height(), hBar = 70;
    if($(window).width() < 767)
      hBar = 60;
    $("#content").css("height", (wHeight - hBar) + "px");
  } else {
     p.options._currentCode = '#';
     this.reloadInvGrid();
  }
}
grid$m48_1Distribute.prototype.selectItemChanged = function(dt){
  var p = this._dir;
  this.reloadInvGrid();
}
grid$m48_1Distribute.prototype.reloadInvGrid = function(){
  var p = this._dir, phd = p.options._dirHD, m = phd.options.memvars, g = p.grid(), r = g._currRow||0, dt = g.data, curr = dt.val(r, 'ma_kh') + '#' + dt.val(r, 'id');
  if (phd && dt.count() > 0 && curr != p.options._currentCode) {
    m.add([['id', 'I', dt.val(r, 'id')], ['xu_ly', 'I', p.options._xu_ly], ['ma_kh', 'C', dt.val(r, 'ma_kh')], ['ma_nt', 'C', dt.val(r, 'ma_nt')], ['unit_id', 'I', dt.val(r, 'unit_id')], ['tien_nt', 'N', dt.val(r, 'tien_nt')]]);
    p.options._currentCode = curr;
    phd._refresh();
  }
}
grid$m48_1Distribute.prototype.beforeButtonGridClick = function (id, gindex, r) {
  var p = this._dir, g = p.grid();
  switch (id) {
    case 'refresh':
      p.options._currentCode = '#';
      this.reloadInvGrid();
      break;
    default:
      break;
  }
  return true;
}

css.text:

.table-bottom{
left: 0px!important;
  height: calc(100% - 77px);
  top: 0px;
  position: relative;
  margin-top: 27px;
  clear: both;
  border-bottom: 1px solid #ddd;
}
#content .dir{
  position: relative !important;
  height: 50%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
    margin-top: 42px;
    height: calc(100% - 92px);
  }
}
